// session hanging off the partner gateway collapsed that view to a single
// row: the one shape that makes a grouping control look broken. Each
// person also gets at least one, so no one's tab reads "no connections"
// while their usage panels show a week of traffic.
func (q *Queries) ServersInsertUserSessionClients(ctx context.Context, arg ServersInsertUserSessionClientsParams) error {
	_, err := q.db.Exec(ctx, serversInsertUserSessionClients,
		arg.LinearClientID,
		arg.ProjectID,
		arg.OrgID,
		arg.LinearIssuerID,
		arg.SlackClientID,
		arg.SlackIssuerID,
		arg.GatewayClientID,
		arg.GatewayIssuerID,
	)
	return err
}

